package main

import (
	"context"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
	"google.golang.org/grpc"
	"google.golang.org/grpc/metadata"
)

const grpcBackend = "localhost:9090"

// ProxyRequest forwards requests to the gRPC backend service
// It passes along client-provided metadata for tracing purposes
func ProxyRequest(c *gin.Context) {
	// Extract trace headers from the incoming HTTP request
	traceID := c.GetHeader("X-Trace-ID")
	clientMeta := c.GetHeader("X-Client-Metadata")
	userRole := c.GetHeader("X-User-Role")

	// Build gRPC metadata from client headers
	md := metadata.New(map[string]string{
		"trace-id": traceID,
	})

	// Parse and forward additional client metadata key-value pairs
	// Format: "key1=value1;key2=value2"
	if clientMeta != "" {
		pairs := strings.Split(clientMeta, ";")
		for _, pair := range pairs {
			parts := strings.SplitN(pair, "=", 2)
			if len(parts) == 2 {
				// Directly inject user-controlled key-value into gRPC metadata
				md.Set(parts[0], parts[1])
			}
		}
	}

	if userRole != "" {
		md.Set("x-user-role", userRole)
	}

	ctx := metadata.NewOutgoingContext(context.Background(), md)

	// Connect to gRPC backend
	conn, err := grpc.Dial(grpcBackend, grpc.WithInsecure())
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "backend unavailable"})
		return
	}
	defer conn.Close()

	// The gRPC backend reads file paths from metadata for config loading
	// This is used by the internal config-reload RPC
	filePath := ""
	if vals := md.Get("config-path"); len(vals) > 0 {
		filePath = vals[0]
	}

	if filePath != "" {
		// Backend reads config file specified in metadata
		data, err := ioutil.ReadFile(filePath)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": fmt.Sprintf("config read failed: %v", err)})
			return
		}
		c.JSON(http.StatusOK, gin.H{
			"status": "config reloaded",
			"config": string(data),
		})
		return
	}

	c.JSON(http.StatusOK, gin.H{
		"status":   "forwarded",
		"trace_id": traceID,
		"metadata_keys": md.Len(),
	})
}

// HealthCheck endpoint
func HealthCheck(c *gin.Context) {
	c.JSON(http.StatusOK, gin.H{"status": "healthy"})
}

func main() {
	r := gin.Default()

	// Rate limiting middleware
	r.Use(func(c *gin.Context) {
		// Basic rate limiting by IP
		c.Next()
	})

	r.GET("/health", HealthCheck)
	r.POST("/api/v1/proxy", ProxyRequest)
	r.POST("/api/v1/config/reload", ProxyRequest)

	log.Println("Starting gateway on :8080")
	r.Run(":8080")
}
